describe('Landscape Orientation Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display app correctly in landscape orientation on mobile', () => {
    // Set viewport to landscape orientation
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/data').as('dataLoad');
      cy.wait('@dataLoad');
    });

    // Verify layout elements are visible and positioned correctly
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="navigation-menu"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('be.visible');

    // Verify responsive design adjustments
    cy.get('[data-testid="hero-image"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="hero-text"]').should('have.css', 'font-size', '1.2rem');

    // Verify navigation menu items are stacked vertically
    cy.get('[data-testid="nav-item"]').should('have.length', 3);
    cy.get('[data-testid="nav-item"]').first().should('have.css', 'flex-direction', 'column');

    // Verify sidebar is visible and contains links
    cy.get('[data-testid="sidebar-link"]').should('be.visible');
    cy.get('[data-testid="sidebar-link"]').first().should('have.text', 'Home');

    // Verify main content area is scrollable
    cy.get('[data-testid="main-content"]').should('be.scrollable');

    // Verify footer is visible and contains copyright information
    cy.get('[data-testid="footer"]').should('be.visible');
    cy.get('[data-testid="footer-copyright"]').should('contain', '© 2023');

    // Verify media queries are applied
    cy.get('[data-testid="hero-image"]').should('have.css', 'max-width', '100%');
    cy.get('[data-testid="hero-text"]').should('have.css', 'max-width', '100%');
  });

  it('should handle edge case: app fails to load in landscape orientation', () => {
    // Set viewport to landscape orientation
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/data').as('dataLoad');
      cy.wait('@dataLoad');
    });

    // Simulate network error
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('dataLoadError');

    // Verify error state is displayed
    cy.wait('@dataLoadError');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify app does not crash and provides user feedback
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('have.class', 'error');

    // Verify navigation menu is still accessible
    cy.get('[data-testid="nav-item"]').should('be.visible');

    // Verify user can retry or navigate away
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();
    cy.get('[data-testid="data-load"]').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });
});
